# ---- dbgpd.R ----
dbgpd <-
function (x, y,
model = "log",
mar1 = c(0, 1, 0.1),
mar2 = c(0, 1, 0.1),
dep = 2,
a = 1, b = 1, asy = 0, p = 3,  ...)
{
    dgpd   = NULL
    models = c("log", "psilog", "philog", 
        "neglog", "psineglog" , "phineglog", 
        "bilog" , "negbilog"  , "ct", "taj")#, "smith", "mix")
    if (!(model %in% models))
        stop(paste("'", model, "' is an unknown model.", sep = ""))
    else {
        if (model == "log")
            dbgpd = dbgpd_log(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep)
#        if (model == "smith")
#            dbgpd = dbgpd_smith(x, y, mar1 = mar1, mar2 = mar2,
#                dep = dep)
        if (model == "psilog")
            dbgpd = dbgpd_psilog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, asy = asy, p = p)
        if (model == "philog")
            dbgpd = dbgpd_philog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, asy = asy, p = p)
        if (model == "neglog")
            dbgpd = dbgpd_neglog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep )
        if (model == "psineglog")
            dbgpd = dbgpd_psineglog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, asy = asy, p = p)
        if (model == "phineglog")
            dbgpd = dbgpd_phineglog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, asy = asy, p = p)
        if (model == "bilog")
            dbgpd = dbgpd_bilog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, a = a, b = b)
        if (model == "negbilog")
            dbgpd = dbgpd_negbilog(x, y, mar1 = mar1, mar2 = mar2,
                dep = dep, a = a, b = b)
#        if (model == "mix")
#            dbgpd = dbgpd_mix(x, y, mar1 = mar1, mar2 = mar2)
        if (model == "ct")
            dbgpd = dbgpd_ct(x, y, mar1 = mar1, mar2 = mar2,
                a = a, b = b)
        if (model == "taj")
            dbgpd = dbgpd_taj(x, y, mar1 = mar1, mar2 = mar2,
                a = a, b = b)
    }
dbgpd
}

# ---- dbgpd_bilog.R ----
dbgpd_bilog <-
function(x,y,mar1=c(0,1,0.1),mar2=c(0,1,0.1),a=1/2,b=1/2,...){

                  param         = as.numeric(c(mar1,mar2,a,b))
                  mux           = param[1]; muy    = param[4]
                  sigx          = param[2]; sigy   = param[5]
                  gamx          = param[3]; gamy   = param[6]
                  a             = param[7]; b      = param[8]

hxy               = NULL
error             = FALSE 
if(sigx<0 | sigy<0 | a<0 | b<0 | a>1 | b>1) error = TRUE
if(!error){
                  hxy           = NA
                  tx            = (1+gamx*(x-mux)/sigx)^(1/gamx)
                  ty            = (1+gamy*(y-muy)/sigy)^(1/gamy)
                  tx0           = (1+gamx*(-mux)/sigx)^(1/gamx)
                  ty0           = (1+gamy*(-muy)/sigy)^(1/gamy)
                  dtx           = (1/sigx)*pmax((1+gamx*(x-mux)/sigx),0)^(1/gamx-1)
                  dty           = (1/sigy)*pmax((1+gamy*(y-muy)/sigy),0)^(1/gamy-1)

            ###################
            ## spectral density
            ###################


            w             = tx/(tx+ty)
            l             = length(w)
            gma1          = rep(NA,l)

                for(i in 1:l)
                {
                    if(!is.na(w[i])){
                    eqn =function(z) (1-a)*(1-w[i])*(1-z)^b-(1-b)*w[i]*z^a
                    if(w[i] == 0) gma1[i] = 0 else
                    if(w[i] == 1) gma1[i] = 1 else
                    gma1[i] <- uniroot(eqn, lower = 0, upper = 1,tol = .Machine$double.eps^0.5)$root}
                }


            hdens         = function(w,gma=gma1) ((1-a)*(1-gma)*gma^(1-a))/((1-w)*w^2*((1-gma)*a+gma*b))
            dxdymu        = function(x1,y1) -(x1+y1)^(-3)*hdens(x1/(x1+y1))

            ################
            ## V(tx0,ty0)
            ################

            c0            = log(pbvevd(c(0,0), model="bilog", mar1=c(mux,sigx,gamx), mar2=c(muy,sigy,gamy), alpha=a, beta=b))
            hxy           = 1/c0*dxdymu(tx,ty)*dtx*dty
            hxy           = as.numeric(hxy*(1-((x<0)*(y<0))))
 }else stop("invalid parameter(s)")
hxy
}

# ---- dbgpd_ct.R ----
dbgpd_ct <-
function(x,y,mar1=c(0,1,0.1),mar2=c(0,1,0.1),a=1/2,b=1/2,...)
{
Be1               = function(x) pbeta(x,a+1,b)
Be2               = function(x) pbeta(x,a,b+1)
d1Be1             = function(x) dbeta(x,a+1,b)
d1Be2             = function(x) dbeta(x,a,b+1)
d2                = function(x,a1,b1) x^(a1-1)*(a1-1)*(1-x)^(b1-1)/(x*beta(a1, b1))-x^(a1-1)*(1-x)^(b1-1)*(b1-1)/((1-x)*beta(a1, b1))
d2Be1             = function(x) d2(x,a+1,b)
d2Be2             = function(x) d2(x,a,b+1)
Qxy               = function(x,y) a*1/y/(a*1/y+b*1/x)
dxQxy             = function(x,y) a*b/(y*(a/y+b/x)^2*x^2)
dyQxy             = function(x,y) -a/(y^2*(a/y+b/x))+a^2/(y^3*(a/y+b/x)^2)
dxdyQxy           = function(x,y) -a*b/(y^2*(a/y+b/x)^2*x^2)+2*a^2*b/(y^3*(a/y+b/x)^3*x^2)
mu                = function(x,y) 1/x*(1-Be1(Qxy(x,y)))+1/y*Be2(Qxy(x,y))
dxdymu            = function(x,y)
1/x^2*d1Be1(Qxy(x,y))*dyQxy(x,y)-
1/x*d2Be1(Qxy(x,y))*dxQxy(x,y)*dyQxy(x,y)-
1/x*d1Be1(Qxy(x,y))*dxdyQxy(x,y)-
1/y^2*d1Be2(Qxy(x,y))*dxQxy(x,y)+
1/y*d2Be2(Qxy(x,y))*dxQxy(x,y)*dyQxy(x,y)+
1/y*d1Be2(Qxy(x,y))*dxdyQxy(x,y)

                  param         = as.numeric(c(mar1,mar2,a,b))
                  mux           = param[1]; muy    = param[4]
                  sigx          = param[2]; sigy   = param[5]
                  gamx          = param[3]; gamy   = param[6]
                  a             = param[7]; b      = param[8]
                  
hxy               = NULL
error             = FALSE 
if(sigx<0 | sigy<0 | a<0 | b<0 ) error = TRUE
if(!error){
                  hxy           = NA
                  tx            = (1+gamx*(x-mux)/sigx)^(1/gamx)
                  ty            = (1+gamy*(y-muy)/sigy)^(1/gamy)
                  tx0           = (1+gamx*(-mux)/sigx)^(1/gamx)
                  ty0           = (1+gamy*(-muy)/sigy)^(1/gamy)
                  dtx           = (1/sigx)*pmax((1+gamx*(x-mux)/sigx),0)^(1/gamx-1)
                  dty           = (1/sigy)*pmax((1+gamy*(y-muy)/sigy),0)^(1/gamy-1)
                  c0            = -mu(tx0,ty0)
                  hxy           = 1/c0*dxdymu(tx,ty)*dtx*dty
                  hxy           = as.numeric(hxy*(1-((x<0)*(y<0))))
}else stop("invalid parameter(s)")
hxy
}

# ---- dbgpd_log.R ----
dbgpd_log <-
function
(x, y,
mar1 = c(0, 1, 0.1), mar2 = c(0, 1, 0.1),
dep = 2, ...)
{
    mu1     = expression((x^(-alpha) + y^(-alpha))^(1/alpha))
    dmu1    = D(mu1,"x")
    ddmu1   = D(dmu1,"y")
    mu      = function(x, y) eval({x<-x; y<-y; mu1})
    dxdymu  = function(x, y) eval({x<-x; y<-y; ddmu1})

    param   = as.numeric(c(mar1, mar2, dep))
    mux     = param[1]; muy   = param[4]
    sigx    = param[2]; sigy  = param[5]
    gamx    = param[3]; gamy  = param[6]
    alpha   = param[7]
    hxy     = NULL

    error = FALSE
    if (sigx < 0 | sigy < 0 | alpha < 1) error = TRUE
    if (!error)
    {hxy   = NA
      tx    = (1 + gamx * (x - mux)/sigx)^(1/gamx)
      ty    = (1 + gamy * (y - muy)/sigy)^(1/gamy)
      tx0   = (1 + gamx * (-mux)/sigx)^(1/gamx)
      ty0   = (1 + gamy * (-muy)/sigy)^(1/gamy)
      dtx   = (1/sigx) * pmax((1 + gamx * (x - mux)/sigx), 0)^(1/gamx - 1)
      dty   = (1/sigy) * pmax((1 + gamy * (y - muy)/sigy), 0)^(1/gamy - 1)
      c0    = -mu(tx0, ty0)
      hxy   = 1/c0 * dxdymu(tx, ty) * dtx * dty
      hxy   = as.numeric(hxy * (1 - ((x < 0) * (y < 0))))
}
    else stop("invalid parameter(s)")
    hxy
}

# ---- dbgpd_mix.R ----
dbgpd_mix <-
function(x,y,mar1=c(0,1,0.1),mar2=c(0,1,0.1),...)
{
mu                = function(x,y) 1/x+1/y-alpha/(x+y)
dxdymu            = function(x,y) -2*alpha/(x+y)^3

                  param         = as.numeric(c(mar1,mar2))
                  mux           = param[1]; muy    = param[4]
                  sigx          = param[2]; sigy   = param[5]
                  gamx          = param[3]; gamy   = param[6]
                  alpha         = 1

hxy               = NULL
error             = FALSE 
if(sigx<0 | sigy<0 ) error= TRUE
if(!error){

                  tx            = (1+gamx*(x-mux)/sigx)^(1/gamx)
                  ty            = (1+gamy*(y-muy)/sigy)^(1/gamy)
                  tx0           = (1+gamx*(-mux)/sigx)^(1/gamx)
                  ty0           = (1+gamy*(-muy)/sigy)^(1/gamy)
                  dtx           = (1/sigx)*pmax((1+gamx*(x-mux)/sigx),0)^(1/gamx-1)
                  dty           = (1/sigy)*pmax((1+gamy*(y-muy)/sigy),0)^(1/gamy-1)
                  c0            = -mu(tx0,ty0)
                  hxy           = 1/c0*dxdymu(tx,ty)*dtx*dty
                  hxy           = as.numeric(hxy*(1-((x<0)*(y<0))))
}else stop("invalid parameter(s)")
hxy
}

# ---- dbgpd_negbilog.R ----
dbgpd_negbilog <-
function(x,y,mar1=c(0,1,0.1),mar2=c(0,1,0.1),a=1/2,b=1/2,...){

                  param         = as.numeric(c(mar1,mar2,-a,-b))
                  mux           = param[1]; muy    = param[4]
                  sigx          = param[2]; sigy   = param[5]
                  gamx          = param[3]; gamy   = param[6]
                  a             = param[7]; b      = param[8]
hxy               = NULL
error             = FALSE 
if(sigx<0 | sigy<0 | a>0 | b>0) error = TRUE
if(!error){

                  hxy           = NA
                  tx            = (1+gamx*(x-mux)/sigx)^(1/gamx)
                  ty            = (1+gamy*(y-muy)/sigy)^(1/gamy)
                  tx0           = (1+gamx*(-mux)/sigx)^(1/gamx)
                  ty0           = (1+gamy*(-muy)/sigy)^(1/gamy)
                  dtx           = (1/sigx)*pmax((1+gamx*(x-mux)/sigx),0)^(1/gamx-1)
                  dty           = (1/sigy)*pmax((1+gamy*(y-muy)/sigy),0)^(1/gamy-1)

            ###################
            ## spectral density
            ###################

            w             = tx/(tx+ty)
            l             = length(w)
            gma1          = rep(NA,l)

                for(i in 1:l)
                {
                    eqn =function(z) (1-a)*(1-w[i])*(1-z)^b-(1-b)*w[i]*z^a
                    if(w[i] == 0) gma1[i] <- 0 else
                    if(w[i] == 1) gma1[i] <- 1 else
                    gma1[i] <- uniroot(eqn, lower = 0, upper = 1,tol = .Machine$double.eps^0.5)$root
                }

            hdens         = function(w,gma=gma1) -((1-a)*(1-gma)*gma^(1-a))/((1-w)*w^2*((1-gma)*a+gma*b))
            dxdymu        = function(x1,y1) -(x1+y1)^(-3)*hdens(x1/(x1+y1))

            ################
            ## V(tx0,ty0)
            ################

            c0            = log(pbvevd(c(0,0), model="negbilog", mar1=c(mux,sigx,gamx), mar2=c(muy,sigy,gamy), alpha=(-a), beta=(-b)))
            hxy           = 1/c0*dxdymu(tx,ty)*dtx*dty
            hxy           = as.numeric(hxy*(1-((x<0)*(y<0))))
 }else stop("invalid parameter(s)")
hxy
}

# ---- dbgpd_neglog.R ----
dbgpd_neglog <-
function
(x, y,
mar1 = c(0, 1, 0.1), mar2 = c(0, 1, 0.1),dep = 1.5, ...)
{
    mu1     = expression(1/x + 1/y - (x^(alpha) + y^(alpha))^(-1/alpha))
    dmu1    = D(mu1,"x")
    ddmu1   = D(dmu1,"y")
    mu      = function(x, y) eval({x<-x; y<-y; mu1})
    dxdymu  = function(x, y) eval({x<-x; y<-y; ddmu1})

    param   = as.numeric(c(mar1, mar2, dep))
    mux     = param[1]; muy   = param[4]
    sigx    = param[2]; sigy  = param[5]
    gamx    = param[3]; gamy  = param[6]
    alpha   = param[7]
    hxy     = NULL

    error = FALSE
    if (sigx < 0 | sigy < 0 | alpha < 0) error = TRUE
    if (!error)
    {hxy   = NA
      tx    = (1 + gamx * (x - mux)/sigx)^(1/gamx)
      ty    = (1 + gamy * (y - muy)/sigy)^(1/gamy)
      tx0   = (1 + gamx * (-mux)/sigx)^(1/gamx)
      ty0   = (1 + gamy * (-muy)/sigy)^(1/gamy)
      dtx   = (1/sigx) * pmax((1 + gamx * (x - mux)/sigx), 0)^(1/gamx - 1)
      dty   = (1/sigy) * pmax((1 + gamy * (y - muy)/sigy), 0)^(1/gamy - 1)
      c0    = -mu(tx0, ty0)
      hxy   = 1/c0 * dxdymu(tx, ty) * dtx * dty
      hxy   = as.numeric(hxy * (1 - ((x < 0) * (y < 0))))
}
    else stop("invalid parameter(s)")
    hxy
}

# ---- dbgpd_philog.R ----
dbgpd_philog <-
function 
(x, y,
mar1 = c(0, 1, 0.1), mar2 = c(0, 1, 0.1),
dep = 2, asy = 0, p = 2, compare=2, ...)
{
    A1    = expression((x^alpha + (1 - x)^alpha)^(1/alpha))
    fi1   = expression(t+((64*a*(c^5-c^4-2*c^3-2*c^2+5*c-2)*c^5)/((c+1)^2*(c-1)^2
*(-1+2*c)*(1+2*c^2-3*c)))*t^6+(-32*a*(5*c^6-2*c^5-13*c^4-12*c^3+15*c^2+6*c-6)*
c^4/((c+1)^2*(c-1)^2*(-1+2*c)*(1+2*c^2-3*c)))*t^5+(32*c^3*a*(4*c^7+3*c^6-14*c^5-
15*c^4+23*c^2-8*c-2)/((c+1)^2*(c-1)^2*(-1+2*c)*(1+2*c^2-3*c)))*t^4+(-(32*(c^7+4*
c^6-5*c^5-10*c^4-5*c^3+12*c^2+2*c-4))*a*c^3/((1+2*c^2-3*c)*(c+1)^2*
(4*c-1+2*c^3-5*c^2)))*t^3+((32*c^3*a*(c^6-3*c^4-c^2+4*c-2))/((1+2*c^2-3*c)*
(c+1)^2*(4*c-1+2*c^3-5*c^2)))*t^2)
#psi1=a ilyen magassagban megy at = ez kene legyen az asy
#psi2=c metszespont reciproka

    d1A1  = D(A1,"x")
    d2A1  = D(d1A1,"x")
    A     = function(x, alpha) eval({x<-x; alpha<-alpha; A1})
    d1A   = function(x, alpha) eval({x<-x; alpha<-alpha; d1A1})
    d2A   = function(x, alpha) eval({x<-x; alpha<-alpha; d2A1})
    d1fi1 = D(fi1,"t")
    d2fi1 = D(d1fi1,"t")
    fi    = function(t, a, c) eval({t<-t; c<-c; a<-a; fi1})
    d1fi  = function(t, a, c) eval({t<-t; c<-c; a<-a; d1fi1})
    d2fi  = function(t, a, c) eval({t<-t; c<-c; a<-a; d2fi1})

    Afi   = function(t, alpha, a, c) A(fi(t, a, c), alpha)
    d1Afi = function(t, alpha, a, c) d1A(fi(t, a, c), alpha) * d1fi(t, a, c)
    d2Afi = function(t, alpha, a, c) d2A(fi(t, a, c), alpha) * (d1fi(t, a, c))^2 + d1A(fi(t, a, c), alpha) * d2fi(t,a, c)
    mu    = function(x, y, alpha, a, c) (1/x + 1/y) * Afi(x/(x + y), alpha, a, c)

    param = as.numeric(c(mar1, mar2, dep, asy, p))
    mux   = param[1]; muy   = param[4]
    sigx  = param[2]; sigy  = param[5]
    gamx  = param[3]; gamy  = param[6]
    alpha = param[7]
    asy   = param[8]; p     = param[9]
    
    hxy   = NULL
    error = FALSE
    xx    = seq(0, 1, 0.005)
   
    if (min(d2Afi(xx, alpha, asy, p), na.rm = TRUE) < -2.220447e-16 ) error = TRUE
    if (sigx < 0 | sigy < 0 | alpha < 1.1 | p < 1.3 | p > 5) error = TRUE 
    if (!error)
    {
    tx    = (1 + gamx * (x - mux)/sigx)^(1/gamx)
    ty    = (1 + gamy * (y - muy)/sigy)^(1/gamy)
    tx0   = (1 + gamx * (-mux)/sigx)^(1/gamx)
    ty0   = (1 + gamy * (-muy)/sigy)^(1/gamy)
    dtx   = (1/sigx) * pmax((1 + gamx * (x - mux)/sigx), 0)^(1/gamx -1)
    dty   = (1/sigy) * pmax((1 + gamy * (y - muy)/sigy), 0)^(1/gamy -1)
    c0    = -mu(tx0, ty0, alpha, asy, p)
    mu1   = tx/(tx + ty)
    dxmu1 = ty/(tx + ty)^2
    dymu1 = (-tx)/(tx + ty)^2
    dxdymu1 = (tx - ty)/(tx + ty)^3
    dxdymu = (-1) * d1Afi(mu1, alpha, asy, p) * (dymu1/tx^2 + dxmu1/ty^2) + (1/tx + 1/ty) * (d2Afi(mu1, alpha,asy, p) * dxmu1 * dymu1 + d1Afi(mu1, alpha, asy,p) * dxdymu1)
    hxy   = 1/c0 * dxdymu * dtx * dty
    hxy   = as.numeric(hxy * (1 - ((x < 0) * (y < 0))))
    hxy
    }
    else stop("invalid parameter(s)")
    hxy
}

