# ---- dtr.R ----
dtr <-
function(x, gm, mu, sg) eval({x<-x; gm<-gm; mu<-mu; sg<-sg; .dtr})

# ---- fbgpd.R ----
fbgpd <-
function(initpar,dat,model="log",fixed=FALSE,control=list(maxit=50000),psi=3,...)
{
est         = optim(initpar,bgpd_maxlik,dat=dat,model=model,control=control,fixed=fixed,psi=psi)
if(fixed==TRUE) est$par[1]=0
est
}

# ---- mgpd-internal.R ----
.Alog <-
expression(((t1)^(alpha) + (t2)^(alpha) + (1 - t1 - t2)^(alpha))^(1/alpha))
.Aneglog <-
expression(1 - ((t1)^(-alpha) + (t2)^(-alpha) + (1 - t1 - t2)^(-alpha))^(-1/alpha))
.d11Alog <-
quote(((t1)^(alpha) + (t2)^(alpha) + (1 - t1 - t2)^(alpha))^(((1/alpha) - 
    1) - 1) * (((1/alpha) - 1) * ((t1)^((alpha) - 1) * (alpha) - 
    (1 - t1 - t2)^((alpha) - 1) * (alpha))) * ((1/alpha) * ((t1)^((alpha) - 
    1) * (alpha) - (1 - t1 - t2)^((alpha) - 1) * (alpha))) + 
    ((t1)^(alpha) + (t2)^(alpha) + (1 - t1 - t2)^(alpha))^((1/alpha) - 
        1) * ((1/alpha) * ((t1)^(((alpha) - 1) - 1) * ((alpha) - 
        1) * (alpha) + (1 - t1 - t2)^(((alpha) - 1) - 1) * ((alpha) - 
        1) * (alpha))))
.d11Aneglog <-
quote(-(((t1)^(-alpha) + (t2)^(-alpha) + (1 - t1 - t2)^(-alpha))^(((-1/alpha) - 
    1) - 1) * (((-1/alpha) - 1) * ((t1)^((-alpha) - 1) * (-alpha) - 
    (1 - t1 - t2)^((-alpha) - 1) * (-alpha))) * ((-1/alpha) * 
    ((t1)^((-alpha) - 1) * (-alpha) - (1 - t1 - t2)^((-alpha) - 
        1) * (-alpha))) + ((t1)^(-alpha) + (t2)^(-alpha) + (1 - 
    t1 - t2)^(-alpha))^((-1/alpha) - 1) * ((-1/alpha) * ((t1)^(((-alpha) - 
    1) - 1) * ((-alpha) - 1) * (-alpha) + (1 - t1 - t2)^(((-alpha) - 
    1) - 1) * ((-alpha) - 1) * (-alpha)))))
.d11psiAlog <-
quote(((t1 + A1 * (t1 * (1 - t2 - t1))^B1)^alpha + (t2 + A2 * 
    (t2 * (1 - t1 - t2))^B2)^alpha + (1 - (t1 + A1 * (t1 * (1 - 
    t2 - t1))^B1) - (t2 + A2 * (t2 * (1 - t1 - t2))^B2))^alpha)^(((1/alpha) - 
    1) - 1) * (((1/alpha) - 1) * ((t1 + A1 * (t1 * (1 - t2 - 
    t1))^B1)^(alpha - 1) * (alpha * (1 + A1 * ((t1 * (1 - t2 - 
    t1))^(B1 - 1) * (B1 * ((1 - t2 - t1) - t1))))) - (t2 + A2 * 
    (t2 * (1 - t1 - t2))^B2)^(alpha - 1) * (alpha * (A2 * ((t2 * 
    (1 - t1 - t2))^(B2 - 1) * (B2 * t2)))) - (1 - (t1 + A1 * 
    (t1 * (1 - t2 - t1))^B1) - (t2 + A2 * (t2 * (1 - t1 - t2))^B2))^(alpha - 
    1) * (alpha * (1 + A1 * ((t1 * (1 - t2 - t1))^(B1 - 1) * 
    (B1 * ((1 - t2 - t1) - t1))) - A2 * ((t2 * (1 - t1 - t2))^(B2 - 
    1) * (B2 * t2)))))) * ((1/alpha) * ((t1 + A1 * (t1 * (1 - 
    t2 - t1))^B1)^(alpha - 1) * (alpha * (1 + A1 * ((t1 * (1 - 
    t2 - t1))^(B1 - 1) * (B1 * ((1 - t2 - t1) - t1))))) - (t2 + 
    A2 * (t2 * (1 - t1 - t2))^B2)^(alpha - 1) * (alpha * (A2 * 
    ((t2 * (1 - t1 - t2))^(B2 - 1) * (B2 * t2)))) - (1 - (t1 + 
    A1 * (t1 * (1 - t2 - t1))^B1) - (t2 + A2 * (t2 * (1 - t1 - 
    t2))^B2))^(alpha - 1) * (alpha * (1 + A1 * ((t1 * (1 - t2 - 
    t1))^(B1 - 1) * (B1 * ((1 - t2 - t1) - t1))) - A2 * ((t2 * 
    (1 - t1 - t2))^(B2 - 1) * (B2 * t2)))))) + ((t1 + A1 * (t1 * 
    (1 - t2 - t1))^B1)^alpha + (t2 + A2 * (t2 * (1 - t1 - t2))^B2)^alpha + 
    (1 - (t1 + A1 * (t1 * (1 - t2 - t1))^B1) - (t2 + A2 * (t2 * 
        (1 - t1 - t2))^B2))^alpha)^((1/alpha) - 1) * ((1/alpha) * 
    ((t1 + A1 * (t1 * (1 - t2 - t1))^B1)^((alpha - 1) - 1) * 
        ((alpha - 1) * (1 + A1 * ((t1 * (1 - t2 - t1))^(B1 - 
            1) * (B1 * ((1 - t2 - t1) - t1))))) * (alpha * (1 + 
        A1 * ((t1 * (1 - t2 - t1))^(B1 - 1) * (B1 * ((1 - t2 - 
            t1) - t1))))) + (t1 + A1 * (t1 * (1 - t2 - t1))^B1)^(alpha - 
        1) * (alpha * (A1 * ((t1 * (1 - t2 - t1))^((B1 - 1) - 
        1) * ((B1 - 1) * ((1 - t2 - t1) - t1)) * (B1 * ((1 - 
        t2 - t1) - t1)) - (t1 * (1 - t2 - t1))^(B1 - 1) * (B1 * 
        (1 + 1))))) + ((t2 + A2 * (t2 * (1 - t1 - t2))^B2)^(alpha - 
        1) * (alpha * (A2 * ((t2 * (1 - t1 - t2))^((B2 - 1) - 
        1) * ((B2 - 1) * t2) * (B2 * t2)))) + (t2 + A2 * (t2 * 
        (1 - t1 - t2))^B2)^((alpha - 1) - 1) * ((alpha - 1) * 
        (A2 * ((t2 * (1 - t1 - t2))^(B2 - 1) * (B2 * t2)))) * 
        (alpha * (A2 * ((t2 * (1 - t1 - t2))^(B2 - 1) * (B2 * 
            t2))))) - ((1 - (t1 + A1 * (t1 * (1 - t2 - t1))^B1) - 
        (t2 + A2 * (t2 * (1 - t1 - t2))^B2))^(alpha - 1) * (alpha * 
        (A1 * ((t1 * (1 - t2 - t1))^((B1 - 1) - 1) * ((B1 - 1) * 
            ((1 - t2 - t1) - t1)) * (B1 * ((1 - t2 - t1) - t1)) - 
            (t1 * (1 - t2 - t1))^(B1 - 1) * (B1 * (1 + 1))) + 
