# ---- ml_taj.R ----
ml_taj <-
function(param,dat,mlmax=1e+15,fixed=FALSE,...)
{

loglik       = mlmax
hxy          = NA
x            = dat[,1]
y            = dat[,2]
error        = FALSE

mux          = param[1]; muy    = param[4]
sigx         = param[2]; sigy   = param[5]
gamx         = param[3]; gamy   = param[6]
a            = param[7]; b      = param[8]
mu           = function(x,y) ((1/x)^(2*a)+2*(1+b)*(1/x/y)^(a)+(1/y)^(2*a))^(1/2/a)
dxdymu       = function(x,y) (1/4)*((1/x)^(2*a)+(2*(1+b))*(1/(x*y))^a+(1/y)^(2*a))^
(1/(2*a))*(-(2*(1+b))*(1/(x*y))^a*a/y-2*(1/y)^(2*a)*a/y)*(-2*(1/x)^(2*a)*a/x-(2*(1+b))*
(1/(x*y))^a*a/x)/(a^2*((1/x)^(2*a)+(2*(1+b))*(1/(x*y))^a+(1/y)^(2*a))^2)+((1/x)^(2*a)+
(2*(1+b))*(1/(x*y))^a+(1/y)^(2*a))^(1/(2*a))*a*(1+b)*(1/(x*y))^a/(y*x*((1/x)^(2*a)+
(2*(1+b))*(1/(x*y))^a+(1/y)^(2*a)))-(1/2)*((1/x)^(2*a)+(2*(1+b))*(1/(x*y))^a+(1/y)^
(2*a))^(1/(2*a))*(-2*(1/x)^(2*a)*a/x-(2*(1+b))*(1/(x*y))^a*a/x)*(-(2*(1+b))*(1/(x*y))^
a*a/y-2*(1/y)^(2*a)*a/y)/(a*((1/x)^(2*a)+(2*(1+b))*(1/(x*y))^a+(1/y)^(2*a))^2)

if(sigx<0 | sigy<0 | a<1 | b<=-1 | (b>(2*a-2))) error = TRUE
if(fixed==TRUE) {mux=0}
if(error) loglik = mlmax
if(!error)
{
tx           = (1+gamx*(x-mux)/sigx)^(1/gamx)
ty           = (1+gamy*(y-muy)/sigy)^(1/gamy)
tx0          = (1+gamx*(-mux)/sigx)^(1/gamx)
ty0          = (1+gamy*(-muy)/sigy)^(1/gamy)
dtx          = (1/sigx)*pmax((1+gamx*(x-mux)/sigx),0)^(1/gamx-1)
dty          = (1/sigy)*pmax((1+gamy*(y-muy)/sigy),0)^(1/gamy-1)
c0           = -mu(tx0,ty0)
hxy          = 1/c0*dxdymu(tx,ty)*dtx*dty
hxy          = as.numeric(hxy*(1-((x<0)*(y<0))))
loglik       = -sum(log(hxy))
}
if(min(1+gamx*(x-mux)/sigx)<0) loglik=mlmax
if(min(1+gamy*(y-muy)/sigy)<0) loglik=mlmax
loglik
}

# ---- mulog.R ----
mulog <-
function(t1, t2, t3, alpha=2   ,... ) eval({t1<-t1; t2<-t2; t3<-t3; alpha<-alpha;   .mulog})

# ---- muneglog.R ----
muneglog <-
function(t1, t2, t3, alpha=2   ,... ) eval({t1<-t1; t2<-t2; t3<-t3; alpha<-alpha;   .muneglog})

# ---- mupsilog.R ----
mupsilog <-
function(t1, t2, t3, alpha=2,   A1=0, A2=0, B1=2, B2=2,... ) eval({t1<-t1; t2<-t2; t3<-t3; alpha<-alpha;
                                                                              A1<-A1; A2<-A2; B1<-B1; B2<-B2;  .mupsilog})

# ---- mupsineglog.R ----
mupsineglog <-
function(t1, t2, t3, alpha=2,   A1=0, A2=0, B1=2, B2=2,... ) eval({t1<-t1; t2<-t2; t3<-t3; alpha<-alpha;
                                                                              A1<-A1; A2<-A2; B1<-B1; B2<-B2;  .mupsineglog})

# ---- pbgpd.R ----
pbgpd <-
function (x, y,
model = "log",
mar1 = c(0, 1, 0.1),
mar2 = c(0, 1, 0.1),
dep = 2,
a = 1/2, b = 1/2, asy = 0, p = 3,  ...)
{
    pbgpd   = NULL    
    models = c("log", "psilog", "philog", 
        "neglog", "psineglog" , "phineglog", 
        "bilog" , "negbilog"  , "ct", "taj")#, "smith", "mix")
    if (!(model %in% models))
        stop(paste("'", model, "' is an unknown model.", sep = ""))
    else {
        if (model == "log")
            pbgpd = pbgpd_log(x, y, mar1 = mar1, mar2 = mar2, dep = dep)
        if (model == "psilog")
            pbgpd = pbgpd_psilog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, asy = asy, p = p)
        if (model == "philog")
            pbgpd = pbgpd_philog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, asy = asy, p = p)
        if (model == "neglog")
            pbgpd = pbgpd_neglog(x, y, mar1 = mar1, mar2 = mar2, dep = dep )
        if (model == "psineglog")
            pbgpd = pbgpd_psineglog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, asy = asy, p = p)
        if (model == "phineglog")
            pbgpd = pbgpd_phineglog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, asy = asy, p = p)
        if (model == "bilog")
            pbgpd = pbgpd_bilog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, a = a, b = b)
        if (model == "negbilog")
            pbgpd = pbgpd_negbilog(x, y, mar1 = mar1, mar2 = mar2, dep = dep, a = a, b = b)
        #if (model == "mix")
        #    pbgpd = pbgpd_mix(x, y, mar1 = mar1, mar2 = mar2)
        if (model == "ct")
            pbgpd = pbgpd_ct(x, y, mar1 = mar1, mar2 = mar2, a = a, b = b)
        if (model == "taj")
            pbgpd = pbgpd_taj(x, y, mar1 = mar1, mar2 = mar2, a = a, b = b)
        #if (model == "smith")
        #    pbgpd = pbgpd_smith(x, y, mar1 = mar1, mar2 = mar2, dep = dep)
    }
pbgpd
}

# ---- pbgpd_bilog.R ----
pbgpd_bilog <-
function(x,y,mar1=c(0,1,0.1),mar2=c(0,1,0.1),a=1/2,b=1/2,...){

                  param         = as.numeric(c(mar1,mar2,a,b))
                  mux           = param[1]; muy    = param[4]
                  sigx          = param[2]; sigy   = param[5]
                  gamx          = param[3]; gamy   = param[6]
                  a             = param[7]; b      = param[8]

Hxy               = NULL
error             = FALSE 
if(sigx<0 | sigy<0 | a<0 | b<0 | a>1 | b>1) error = TRUE
if(!error){
            Hxy           = NA
            c0            = log(pbvevd(c(0,0), model="bilog", mar1=c(mux,sigx,gamx), mar2=c(muy,sigy,gamy), alpha=a, beta=b))
            Hxy           = -1/c0*log(
            pbvevd(c(x,y), model="bilog", mar1=c(mux,sigx,gamx), mar2=c(muy,sigy,gamy), alpha=a, beta=b)/
            pbvevd(cbind(pmin(x,0),pmin(y,0)), model="bilog", mar1=c(mux,sigx,gamx), mar2=c(muy,sigy,gamy), alpha=a, beta=b)
            )
 }else stop("invalid parameter(s)")
Hxy
}

