    c0      = -mupsineglog(tx0,ty0,tz0, alpha=alpha, A1=A1, A2=A2, B1=B1, B2=B2)
    Hxyz    = 1/c0 * (mupsineglog(tx, ty, tz, alpha=alpha, A1=A1, A2=A2, B1=B1, B2=B2) 
              - mupsineglog(pmin(tx,rep(tx0,length(tx))), pmin(ty,rep(tx0,length(tx))),pmin(tz,rep(tz0,length(tz))), alpha=alpha, A1=A1, A2=A2, B1=B1, B2=B2))
    } else print("invalid parameter(s)")
Hxyz
